function drawGengarNeonShadow(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.3;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(breathSin) * 3.5;

  // Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 26 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // Gai lưng
  ctx.fillStyle = '#7e22ce';
  ctx.beginPath(); ctx.moveTo(-10, by - 20); ctx.lineTo(0,  by - 38); ctx.lineTo(10, by - 20); ctx.fill();
  ctx.beginPath(); ctx.moveTo(8,   by - 10); ctx.lineTo(28, by - 16); ctx.lineTo(12, by + 4);  ctx.fill();
  ctx.beginPath(); ctx.moveTo(-8,  by - 10); ctx.lineTo(-28,by - 16); ctx.lineTo(-12,by + 4);  ctx.fill();

  // Thân & chân
  ctx.beginPath(); ctx.ellipse(0, by + 10, 22 * sX, 20 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.roundRect(-16, by + 28, 9, 10, 4); ctx.fill();
  ctx.beginPath(); ctx.roundRect(7,   by + 28, 9, 10, 4); ctx.fill();

  // Đầu
  ctx.beginPath(); ctx.ellipse(0, by - 8, 20 * sX, 16 * sY, 0, 0, Math.PI * 2); ctx.fill();
  // Tai
  ctx.beginPath(); ctx.moveTo(-16, by - 18); ctx.lineTo(-26, by - 40); ctx.lineTo(-8, by - 22); ctx.fill();
  ctx.beginPath(); ctx.moveTo(8,   by - 22); ctx.lineTo(26,  by - 40); ctx.lineTo(16, by - 18); ctx.fill();

  // Mắt đỏ
  if (!blink) {
    ctx.fillStyle = '#ef4444';
    ctx.beginPath(); ctx.moveTo(-16, by - 12); ctx.lineTo(-6, by - 16); ctx.lineTo(-6, by - 4); ctx.fill();
    ctx.beginPath(); ctx.moveTo(16,  by - 12); ctx.lineTo(6,  by - 16); ctx.lineTo(6,  by - 4); ctx.fill();
    ctx.fillStyle = '#0f172a';
    ctx.beginPath(); ctx.arc(-9, by - 10, 2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(9,  by - 10, 2, 0, Math.PI * 2); ctx.fill();
  }

  // Nụ cười răng trắng
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.roundRect(-18, by + 2, 36, 12, 6); ctx.fill();
  ctx.strokeStyle = '#0f172a';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(-9, by + 2); ctx.lineTo(-9, by + 14);
  ctx.moveTo(0,  by + 2); ctx.lineTo(0,  by + 14);
  ctx.moveTo(9,  by + 2); ctx.lineTo(9,  by + 14);
  ctx.moveTo(-18,by + 8); ctx.lineTo(18, by + 8);
  ctx.stroke();

  // Tay
  ctx.fillStyle = '#7e22ce';
  ctx.beginPath(); ctx.arc(-18, by + 4, 5, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(18,  by + 4, 5, 0, Math.PI * 2); ctx.fill();

  ctx.restore();
}
